<template>
  <div class="user-dashboard">

    <!-- Profile card -->
    <div class="profile-card">
      <div class="profile-avatar">
        <span>{{ initials }}</span>
      </div>
      <div class="profile-info">
        <h2 class="profile-name">{{ userInfo.user_name || "—" }}</h2>
        <p class="profile-email">
          <v-icon size="14" color="#9e9e9e">mdi-email-outline</v-icon>
          {{ userInfo.user_email || "—" }}
        </p>
        <p class="profile-comment" v-if="userInfo.commentaire">
          {{ userInfo.commentaire }}
        </p>
      </div>
      <div class="profile-actions">
        <v-btn color="#3f51b5" variant="flat" style="color: white;" rounded="lg" size="small"
          @click="showRequestDialog = true">
          <v-icon start size="16">mdi-plus</v-icon>
          Nouvelle demande
        </v-btn>
      </div>
    </div>

    <!-- ═══ Formulaire de demande de congé ═══ -->
