      <v-card rounded="xl">
        <!-- Header -->
        <div class="form-dialog-header">
          <div class="form-dialog-icon">
            <v-icon color="#3f51b5" size="22">mdi-calendar-plus</v-icon>
          </div>
          <div>
            <div class="form-dialog-title">Nouvelle demande de congé</div>
            <div class="form-dialog-sub">{{ userInfo.user_name || "" }}</div>
          </div>
          <v-btn icon variant="text" color="#757575" size="small" class="ml-auto" @click="closeForm">
            <v-icon>mdi-close</v-icon>
          </v-btn>
        </div>

        <v-card-text class="form-dialog-body">
          <v-form ref="requestForm" v-model="formValid" @submit.prevent="submitRequest">
            <!-- {{ congeTypes }} -->
            <div class="form-label">Type de congé <span class="req">*</span></div>
            <v-select v-model="form.type" :items="congeTypes.filter((val) => val.can_be_create == 1)" hide-details
