              placeholder="Sélectionnez un type" :rules="[v => !!v || 'Champ requis']" class="mb-3">
              <template #item="{ item, props }">
                <v-list-item v-bind="props">
                  <template #prepend>
                    <div class="type-dot" :style="{ background: item.raw.color }"></div>
                  </template>
                </v-list-item>
              </template>
            </v-select>
            <div v-if="form.type && form.type.length > 0">
              Solde de {{soldeListe.find((val) => val.id_conge_type == form.type)['CONGE_TYPE::libelle']}} : <v-chip
                style="font-weight: bold;" density="compact" class="py-4"
                :color="congeTypes.find((val) => val.id_conge_type == form.type).color"> {{soldeListe.find((val) =>
                  val.id_conge_type == form.type).solde_disponible}} J </v-chip>
            </div>
            <div v-if="form.type && form.type.length > 0" style="color: grey;font-size: 13px;">
              {{congeTypes.find((val) => val.id_conge_type == form.type).description}}
            </div>
            <!-- Dates -->
            <v-row class="mt-2">
              <v-col cols="6">
                <div class="form-label">Date de début <span class="req">*</span></div>
                <input type="date" :value="form.dateDebut || ''"
                  @change="form.dateDebut = $event.target.value || null; dateDebutError = ''; updateNbrJours()"
                  class="date-input" :class="{ 'date-input--error': dateDebutError }" />
                <div v-if="dateDebutError" class="date-error-msg">{{ dateDebutError }}</div>
              </v-col>
              <v-col cols="6">
                <div class="form-label">Date de fin <span class="req">*</span></div>
                <input type="date" :value="form.dateFin || ''"
                  @change="form.dateFin = $event.target.value || null; dateFinError = ''; updateNbrJours()"
                  class="date-input" :class="{ 'date-input--error': dateFinError }" />
                <div v-if="dateFinError" class="date-error-msg">{{ dateFinError }}</div>
              </v-col>
            </v-row>

            <!-- Résumé jours ouvrés éditable -->
            <div v-if="form.dateDebut && form.dateFin" class="days-summary mt-2">
              <v-icon size="16" color="#3f51b5">mdi-calendar-check-outline</v-icon>
              <input type="number" v-model.number="form.nbrJours" min="0" class="jours-input" />
              <span>jour{{ form.nbrJours !== 1 ? 's' : '' }} ouvré{{ form.nbrJours !== 1 ? 's' : '' }}</span>
            </div>

            <div
              v-if="soldeListe && soldeListe.find((val) => val.id_conge_type == form.type) && soldeListe.find((val) => val.id_conge_type == form.type).solde_disponible && form.nbrJours && form.nbrJours > soldeListe.find((val) => val.id_conge_type == form.type).solde_disponible"
              class="mt-2">
              <v-card variant="flat" class="pa-3" style="color:black; border-radius: 10px;font-size: 14px;"
                color="#EF9A9A">
                <v-icon>mdi-alert</v-icon>
                Le nombre de jours de congé demandés est supérieur au solde de congés disponible
                <div style="font-weight: bold;" align="center" class="mb-2">
                  <v-chip variant="flat" style="background-color: white;font-weight: bold;color: black;">
                    {{ form.nbrJours }} J > {{soldeListe.find((val) => val.id_conge_type == form.type).solde_disponible
                    }} J
                  </v-chip>
                </div>
                (ce calcul ne prend pas
                en compte
                les jours fériés)
              </v-card>
            </div>

            <!-- Motif -->
            <div class="form-label" style="margin-top: 8px">
              Motif <span class="req">*</span>
            </div>
            <v-textarea v-model="form.motif" variant="outlined" density="compact" rounded="lg" rows="3"
              placeholder="Précisez le motif de votre demande..." :rules="[v => !!v || 'Motif requis']" no-resize />

          </v-form>
        </v-card-text>
        <v-card-actions class="form-dialog-actions">
          <v-btn variant="text" color="#757575" @click="closeForm">Annuler</v-btn>
          <v-spacer />
          <v-btn color="#3f51b5" variant="flat" rounded="lg" style="color: white;" :loading="isSubmitting"
            @click="submitRequest">
            Envoyer la demande
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <!-- Contract info grid -->
    <v-row class="info-row">
      <v-col cols="6" sm="4" md="2">
        <div class="info-tile">
          <v-icon size="20" color="#3f51b5">mdi-briefcase-outline</v-icon>
          <span class="info-tile-label">Service</span>
          <span class="info-tile-value">{{ userInfo.service || "—" }}</span>
        </div>
      </v-col>
      <v-col cols="6" sm="4" md="2">
        <div class="info-tile">
          <v-icon size="20" color="#3f51b5">mdi-calendar-star</v-icon>
          <span class="info-tile-label">Date d'embauche</span>
          <span class="info-tile-value">{{ hireDate }}</span>
        </div>
      </v-col>
      <v-col cols="6" sm="4" md="2">
        <div class="info-tile">
          <v-icon size="20" color="#3f51b5">mdi-clock-outline</v-icon>
          <span class="info-tile-label">Heures / semaine</span>
          <span class="info-tile-value">{{ userInfo.heures_hebdo || "—" }}h</span>
        </div>
      </v-col>
      <v-col cols="6" sm="4" md="2">
        <div class="info-tile">
          <v-icon size="20" color="#3f51b5">mdi-calendar-week</v-icon>
          <span class="info-tile-label">Jours travaillés</span>
          <span class="info-tile-value">{{ userInfo.nbr_jours_travaille_par_semaine || "—" }}j / sem.</span>
        </div>
      </v-col>
      <v-col cols="6" sm="4" md="2">
        <div class="info-tile">
          <v-icon size="20" color="#3f51b5">mdi-percent</v-icon>
          <span class="info-tile-label">Taux d'activité</span>
          <span class="info-tile-value">{{ userInfo.taux_activité || "—" }} %</span>
        </div>
      </v-col>
      <v-col cols="6" sm="4" md="2">
        <div class="info-tile" :class="rttEligible ? 'info-tile--yes' : 'info-tile--no'">
          <v-icon size="20" :color="rttEligible ? '#43a047' : '#e53935'">
            {{ rttEligible ? "mdi-check-circle-outline" : "mdi-close-circle-outline" }}
          </v-icon>
          <span class="info-tile-label">Éligibilité RTT</span>
          <span class="info-tile-value" :style="{ color: rttEligible ? '#43a047' : '#e53935' }">
            {{ rttEligible ? "Oui" : "Non" }}
          </span>
        </div>
      </v-col>
    </v-row>

    <!-- Seniority bar -->
    <!-- <div class="seniority-card">
      <div class="seniority-header">
        <v-icon color="#3f51b5" size="18">mdi-medal-outline</v-icon>
        <span class="seniority-title">Jours d'ancienneté</span>
      </div>
      <div class="seniority-body">
        <div class="seniority-stat">
          <span class="seniority-number">{{ userInfo.jour_anciennete_total || 0 }}</span>
          <span class="seniority-label">Total acquis</span>
        </div>
        <div class="seniority-divider"></div>
        <div class="seniority-stat seniority-stat--green">
          <span class="seniority-number">{{ userInfo.jour_anciennete_dispo || 0 }}</span>
          <span class="seniority-label">Disponibles</span>
        </div>
        <div class="seniority-divider"></div>
        <div class="seniority-stat seniority-stat--orange">
          <span class="seniority-number">{{ seniorityUsed }}</span>
          <span class="seniority-label">Utilisés</span>
        </div>
        <div class="seniority-progress-wrap">
          <div class="seniority-progress-track">
            <div class="seniority-progress-fill" :style="{ width: seniorityPercent + '%' }"></div>
          </div>
          <span class="seniority-percent">{{ seniorityPercent }}% utilisé</span>
        </div>
      </div>
    </div> -->

    <div class="section-label mt-4">
      Mon solde <span style="color: grey;font-size: 12px;">(pour l'année en cours)</span>
      <v-btn size="x-small" variant="tonal" :color="hideZeroSolde ? '#3f51b5' : '#9e9e9e'" class="ml-3"
        @click="hideZeroSolde = !hideZeroSolde">
        <v-icon start size="13">{{ hideZeroSolde ? 'mdi-eye' : 'mdi-eye-off' }}</v-icon>
        {{ hideZeroSolde ? 'Tout afficher' : 'Masquer les indisponibles' }}
      </v-btn>
    </div>

    <div v-if="soldeListe.length === 0" class="solde-empty">
      <v-icon color="#bdbdbd" size="28">mdi-calendar-blank-outline</v-icon>
      <span>Aucun solde disponible</span>
    </div>
    <v-row v-else class="mb-4">
      <v-col v-for="(solde, i) in soldeListe.filter(s => !hideZeroSolde || Number(s.solde_disponible) > 0)" :key="i"
        cols="12" sm="6" md="3">
        <div class="solde-card" :style="{ borderLeftColor: getSoldeColor(solde) }">
          <div class="solde-body">
            <h3 class="solde-title">{{ solde.conge_libelle }}</h3>
            <div class="solde-main">
              <span class="solde-dispo" :style="{ color: getSoldeColor(solde) }">{{ solde.solde_disponible }}</span>
              <span class="solde-unit">j dispo.</span>
            </div>
            <div class="solde-footer">
              <span>{{ Number(solde.solde_initial) - Number(solde.solde_disponible) }} utilisés</span>
              <span class="solde-initial">/ {{ solde.solde_initial }} j</span>
            </div>
          </div>
        </div>
      </v-col>
    </v-row>

    <!-- Leave cards -->
    <div class="section-label">
      Mes congés <span style="color: grey;font-size: 12px;">(pour l'année en cours)</span>
      <v-btn size="x-small" variant="tonal" :color="hideZeroConges ? '#3f51b5' : '#9e9e9e'" class="ml-3"
        @click="hideZeroConges = !hideZeroConges">
        <v-icon start size="13">{{ hideZeroConges ? 'mdi-eye' : 'mdi-eye-off' }}</v-icon>
        {{ hideZeroConges ? 'Tout afficher' : 'Masquer les inactifs' }}
        <!-- {{ hideZeroConges ? 'Afficher les inactifs' : 'Masquer les inactifs' }} -->
      </v-btn>
    </div>
    <v-row class="">
      <v-col v-for="(conge, i) in congeTypes.filter(c => !hideZeroConges || getJoursPris(c) > 0)" :key="i" cols="12"
        sm="6" md="3">
        <div class="leave-card">
          <div class="card-top-bar" :style="{ background: conge.color }"></div>
          <div class="card-body">
            <h3 class="card-title">{{ conge.libelle }}</h3>
            <p class="card-subtitle">{{ conge.description }}</p>
            <div class="card-stats">
              <div class="stat-row">
                <span class="stat-label">Demandes validées :</span>
                <span class="stat-value">
                  <div v-if="getConge.history.find((val) => val.id_conge_type == conge.id_conge_type)">
                    {{getConge.history.filter((val) => val.statut == 1 && val.id_conge_type ==
                      conge.id_conge_type).length
                    }}
                  </div>
                  <div v-else> 0 </div>
                </span>
              </div>
              <div class="stat-row">
                <span class="stat-label">Jours pris :</span>
                <span class="stat-value">
                  <div v-if="getConge.history.find((val) => val.id_conge_type == conge.id_conge_type)">
                    {{getConge.history.filter((val) => val.statut == 1 && val.id_conge_type ==
                      conge.id_conge_type).reduce((sum, item) => {
                        return sum + Number(item.nbr_days);
                      }, 0)}}

                  </div>
                  <div v-else>
                    0
                  </div>
                </span>
              </div>
            </div>
          </div>
        </div>
      </v-col>
    </v-row>

    <!-- Demandes en attente -->
    <div class="table-section">
      <div class="table-section-header">
        <div class="table-section-title">
          <v-chip color="#fb8c00" style="font-weight: bold;font-size: 16px;" variant="tonal" class="ml-2">
            <v-icon color="#fb8c00" size="20">mdi-clock-outline</v-icon>
            <span class="pl-1 pr-1">Demandes en attente : </span>
            {{ getConge.pending.length }}
          </v-chip>
        </div>
      </div>
      <v-data-table :headers="pendingHeaders" :items="getConge.pending" :items-per-page="-1" density="compact"
        class="requests-table pb-2" no-data-text="Aucune demande en attente">
        <template #item="{ item }">
          <tr class="pending-row-user" @click="openCancelDialog(item.value)" style="cursor:pointer;"
            title="Cliquez pour annuler cette demande">
            <td>
              <v-chip size="small" style="font-weight: bold;" :color="getTypeColor(item.value.id_conge_type)"
                variant="tonal">
                {{ getTypeName(item.value.id_conge_type) }}
              </v-chip>
            </td>
            <td>{{ formatDate(item.value.debut_timestamp) }}</td>
            <td>{{ formatDate(item.value.fin_timestamp) }}</td>
            <td>{{ item.value.nbr_days || '—' }}</td>
            <td><span class="motif-text">{{ parseMotif(item.value.commentaire) }}</span></td>
            <td>
              <div style="display:flex;align-items:center;gap:8px;">
                <v-chip size="small" style="font-weight: bold;" color="#fb8c00" variant="tonal">
                  <v-icon start size="12">mdi-clock-outline</v-icon>
                  En attente
                </v-chip>
                <v-icon size="16" color="#e53935" title="Annuler">mdi-close-circle-outline</v-icon>
              </div>
            </td>
          </tr>
        </template>
        <template #bottom></template>
      </v-data-table>
    </div>

    <!-- Historique de demandes -->
    <div class="table-section">
      <div class="table-section-header">
        <div class="table-section-title">
          <v-chip color="#3f51b5" style="font-weight: bold;font-size: 16px;" variant="tonal" class="ml-2">
            <v-icon color="#3f51b5" size="18">mdi-history</v-icon>
            <span class="pl-1 pr-1">Historique de demandes : </span>
            <span class=""> {{ getConge.history.length }}</span>
          </v-chip>
          <span class="pt-1" style="color: grey;font-size: 12px;">(les 100 dernières
            demandes)</span>
        </div>
        <v-btn color="#43a047" variant="tonal" size="small" rounded="lg" @click="showExportDialog = true">
          <v-icon start size="16">mdi-microsoft-excel</v-icon>
          Exporter Excel
        </v-btn>
      </div>
      <v-data-table :headers="historyHeaders" :items="getConge.history" :items-per-page="5" density="compact"
        class="requests-table" no-data-text="Aucun historique disponible">
        <template #item="{ item }">
          <tr :class="item.value.statut == 1 ? 'history-row-deletable' : ''"
            :style="item.value.statut == 1 ? 'cursor:pointer;' : ''"
            :title="item.value.statut == 1 ? 'Cliquez pour demander la suppression' : ''"
            @click="item.value.statut == 1 ? openDeleteRequestDialog(item.value) : null">
            <td>
              <v-chip size="small" style="font-weight: bold;" :color="getTypeColor(item.value.id_conge_type)"
                variant="tonal">
                {{ getTypeName(item.value.id_conge_type) }}
              </v-chip>
            </td>
            <td>{{ formatDate(item.value.debut_timestamp) }}</td>
            <td>{{ formatDate(item.value.fin_timestamp) }}</td>
            <td>{{ item.value.nbr_days || '—' }}</td>
            <td><span class="motif-text">{{ parseMotif(item.value.commentaire) }}</span></td>
            <td>
              <v-chip v-if="item.value.statut == 1" style="font-weight: bold;" size="small" color="#43a047"
                variant="tonal">
                <v-icon start size="12">mdi-check-circle-outline</v-icon>
                Validée
                <v-icon end size="13" color="#e53935" class="ml-1">mdi-trash-can-outline</v-icon>
              </v-chip>
              <v-chip v-else-if="item.value.statut == 2" style="font-weight: bold;" size="small" color="#e53935"
                variant="tonal">
                <v-icon start size="12">mdi-close-circle-outline</v-icon>
                Refusée
              </v-chip>
              <v-chip v-else-if="item.value.statut == 3" style="font-weight: bold;" size="small" color="#9e9e9e"
                variant="tonal">
                <v-icon start size="12">mdi-cancel</v-icon>
                Annulée
              </v-chip>
              <v-chip v-else-if="item.value.statut == 4" style="font-weight: bold;" size="small" color="#9c27b0"
                variant="tonal">
                <v-icon start size="12">mdi-trash-can-outline</v-icon>
                Suppression demandée
              </v-chip>
              <v-chip v-else style="font-weight: bold;" size="small" color="#757575" variant="tonal">
                —
              </v-chip>
            </td>
          </tr>
        </template>
      </v-data-table>
    </div>

    <!-- ═══ Dialog annulation demande ═══ -->
    <v-dialog v-model="showCancelDialog" max-width="440" persistent>
      <v-card v-if="requestToCancel" rounded="xl">
        <div class="form-dialog-header">
          <div class="form-dialog-icon" style="background:#ffebee;">
            <v-icon color="#e53935" size="22">mdi-calendar-remove</v-icon>
          </div>
          <div>
            <div class="form-dialog-title">Annuler la demande</div>
            <div class="form-dialog-sub">Cette action est irréversible</div>
          </div>
          <v-btn icon variant="text" color="#757575" size="small" class="ml-auto" @click="showCancelDialog = false">
            <v-icon>mdi-close</v-icon>
          </v-btn>
        </div>

        <v-card-text class="form-dialog-body">
          <div class="cancel-recap">
            <div class="cancel-recap-row">
              <span class="cancel-recap-label">Type</span>
              <v-chip size="small" style="font-weight:bold;" :color="getTypeColor(requestToCancel.id_conge_type)"
                variant="tonal">
                {{ getTypeName(requestToCancel.id_conge_type) }}
              </v-chip>
            </div>
            <div class="cancel-recap-row">
              <span class="cancel-recap-label">Période</span>
              <span class="cancel-recap-value">
                {{ formatDate(requestToCancel.debut_timestamp) }} → {{ formatDate(requestToCancel.fin_timestamp) }}
              </span>
            </div>
            <div class="cancel-recap-row">
              <span class="cancel-recap-label">Jours</span>
              <span class="cancel-recap-value"><strong>{{ requestToCancel.nbr_days || '—' }}</strong></span>
            </div>
            <div class="cancel-recap-row" v-if="parseMotif(requestToCancel.commentaire) !== '—'">
              <span class="cancel-recap-label">Motif</span>
              <span class="cancel-recap-value">{{ parseMotif(requestToCancel.commentaire) }}</span>
            </div>
          </div>
          <div class="cancel-warning">
            <v-icon size="16" color="#e53935">mdi-alert-outline</v-icon>
            Êtes-vous sûr de vouloir annuler cette demande ?
          </div>
        </v-card-text>

        <v-card-actions class="form-dialog-actions">
          <v-btn variant="text" color="#757575" @click="showCancelDialog = false">Retour</v-btn>
          <v-spacer />
          <v-btn color="#e53935" variant="flat" rounded="lg" style="color:white;" :loading="isCancelling"
