            <v-icon start size="16">mdi-close-circle-outline</v-icon>
            Confirmer l'annulation
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <!-- ═══ Dialog demande de suppression ═══ -->
    <v-dialog v-model="showDeleteRequestDialog" max-width="440" persistent>
      <v-card v-if="requestToDelete" rounded="xl">
        <div class="form-dialog-header">
          <div class="form-dialog-icon" style="background:#f3e5f5;">
            <v-icon color="#9c27b0" size="22">mdi-trash-can-outline</v-icon>
          </div>
          <div>
            <div class="form-dialog-title">Demande de suppression</div>
            <div class="form-dialog-sub">Un administrateur traitera votre demande</div>
          </div>
          <v-btn icon variant="text" color="#757575" size="small" class="ml-auto"
            @click="showDeleteRequestDialog = false">
            <v-icon>mdi-close</v-icon>
          </v-btn>
        </div>

        <v-card-text class="form-dialog-body">
          <div class="cancel-recap">
            <div class="cancel-recap-row">
              <span class="cancel-recap-label">Type</span>
              <v-chip size="small" style="font-weight:bold;" :color="getTypeColor(requestToDelete.id_conge_type)"
                variant="tonal">
                {{ getTypeName(requestToDelete.id_conge_type) }}
              </v-chip>
            </div>
            <div class="cancel-recap-row">
              <span class="cancel-recap-label">Période</span>
              <span class="cancel-recap-value">
                {{ formatDate(requestToDelete.debut_timestamp) }} → {{ formatDate(requestToDelete.fin_timestamp) }}
              </span>
            </div>
            <div class="cancel-recap-row">
              <span class="cancel-recap-label">Jours</span>
              <span class="cancel-recap-value"><strong>{{ requestToDelete.nbr_days || '—' }}</strong></span>
            </div>
          </div>
          <div class="form-label" style="margin-top:4px;">
            Motif de la demande <span class="req">*</span>
          </div>
          <v-textarea v-model="deleteRequestMotif" variant="outlined" density="compact" rounded="lg" rows="3"
            placeholder="Expliquez la raison de votre demande de suppression..." :rules="[v => !!v || 'Motif requis']"
            no-resize />

          <div class="cancel-warning" style="background:#f3e5f5;color:#9c27b0;">
            <v-icon size="16" color="#9c27b0">mdi-information-outline</v-icon>
            La demande sera marquée "Suppression demandée" en attendant la validation d'un administrateur.
          </div>
        </v-card-text>

        <v-card-actions class="form-dialog-actions">
          <v-btn variant="text" color="#757575" @click="showDeleteRequestDialog = false">Retour</v-btn>
          <v-spacer />
          <v-btn color="#9c27b0" variant="flat" rounded="lg" style="color:white;" :loading="isRequestingDelete"
            :disabled="!deleteRequestMotif || !deleteRequestMotif.trim()" @click="confirmDeleteRequest">
            <v-icon start size="16">mdi-trash-can-outline</v-icon>
            Envoyer la demande
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <!-- ═══ Dialog export Excel ═══ -->
    <v-dialog v-model="showExportDialog" max-width="400" persistent>
      <v-card rounded="xl">
        <div class="form-dialog-header">
          <div class="form-dialog-icon" style="background:#e8f5e9;">
            <v-icon color="#43a047" size="22">mdi-microsoft-excel</v-icon>
          </div>
          <div>
            <div class="form-dialog-title">Exporter l'historique</div>
            <div class="form-dialog-sub">Choisissez la période à exporter</div>
          </div>
          <v-btn icon variant="text" color="#757575" size="small" class="ml-auto" @click="showExportDialog = false">
            <v-icon>mdi-close</v-icon>
          </v-btn>
        </div>

        <v-card-text class="form-dialog-body">
          <div class="form-label mb-3">Période</div>
          <div class="export-period-grid">
            <div class="export-period-chip" :class="{ 'export-period-chip--active': exportPeriod === 'current' }"
              @click="exportPeriod = 'current'">
              <v-icon size="18">mdi-calendar-today</v-icon>
              Mois en cours
            </div>
            <div class="export-period-chip" :class="{ 'export-period-chip--active': exportPeriod === 'previous' }"
              @click="exportPeriod = 'previous'">
              <v-icon size="18">mdi-calendar-arrow-left</v-icon>
              Mois précédent
            </div>
            <div class="export-period-chip" :class="{ 'export-period-chip--active': exportPeriod === 'all' }"
              @click="exportPeriod = 'all'">
              <v-icon size="18">mdi-calendar-blank-multiple</v-icon>
              Tout
            </div>
            <div class="export-period-chip" :class="{ 'export-period-chip--active': exportPeriod === 'custom' }"
              @click="exportPeriod = 'custom'">
              <v-icon size="18">mdi-calendar-range</v-icon>
              Personnalisé
            </div>
          </div>

          <v-row v-if="exportPeriod === 'custom'" class="mt-3">
            <v-col cols="6">
              <div class="form-label">Du</div>
              <input type="date" v-model="exportDateFrom" class="date-input" />
            </v-col>
            <v-col cols="6">
              <div class="form-label">Au</div>
              <input type="date" v-model="exportDateTo" class="date-input" />
            </v-col>
          </v-row>

          <div class="export-count-info mt-3">
            <v-icon size="15" color="#3f51b5">mdi-information-outline</v-icon>
            <span>{{ filteredHistoryForExport.length }} demande{{ filteredHistoryForExport.length !== 1 ? 's' : '' }} à
              exporter</span>
          </div>
        </v-card-text>

        <v-card-actions class="form-dialog-actions">
          <v-btn variant="text" color="#757575" @click="showExportDialog = false">Annuler</v-btn>
          <v-spacer />
          <v-btn color="#43a047" variant="flat" rounded="lg" style="color:white;"
            :disabled="filteredHistoryForExport.length === 0" @click="doExportExcel">
            <v-icon start size="16">mdi-microsoft-excel</v-icon>
            Exporter
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

  </div>
  <v-snackbar v-model="snackbar.value" :color="snackbar.color">
    <div align="center">
      {{ snackbar.msg }}
    </div>
  </v-snackbar>
</template>

<script>
import moment from 'moment';
import engine from "@/core/index";
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';

export default {
  name: "HomeUser",
  props: {
    userInfo: { type: Object, default: () => ({}) },
    congeTypes: { type: Array, default: () => [] },
  },
  data() {
    return {
      snackbar: {},
      soldeListe: [],
      congeListe: [],
      showRequestDialog: false,
      hideZeroSolde: true,
      hideZeroConges: true,
      dateDebutError: '',
      dateFinError: '',
      formValid: false,
      isSubmitting: false,
      showCancelDialog: false,
      requestToCancel: null,
      isCancelling: false,
      showDeleteRequestDialog: false,
      requestToDelete: null,
      isRequestingDelete: false,
      deleteRequestMotif: '',
      showExportDialog: false,
      exportPeriod: 'all',
      exportDateFrom: null,
      exportDateTo: null,
      form: {
        type: null,
        dateDebut: null,
        dateFin: null,
        nbrJours: null,
        motif: "",
      },
      pendingHeaders: [
        { title: 'Type', key: 'id_conge_type', sortable: true },
        { title: 'Date début', key: 'debut_timestamp', sortable: true },
        { title: 'Date fin', key: 'fin_timestamp', sortable: true },
        { title: 'Jours', key: 'nbr_days', sortable: true },
        { title: 'Motif', key: 'commentaire', sortable: false },
        { title: 'Statut', key: 'statut', sortable: true },
      ],
      historyHeaders: [
        { title: 'Type', key: 'id_conge_type', sortable: true },
        { title: 'Date début', key: 'debut_timestamp', sortable: true },
        { title: 'Date fin', key: 'fin_timestamp', sortable: true },
        { title: 'Jours', key: 'nbr_days', sortable: true },
        { title: 'Motif', key: 'commentaire', sortable: false },
        { title: 'Statut', key: 'statut', sortable: true },
      ],
      leaveTypes: [
        {
          key: "cp",
          title: "Congés Payés",
          subtitle: "25 jours ouvrés par an",
          color: "#3f51b5",
          validated: 0,
          daysTaken: 0,
        },
        {
          key: "rtt",
          title: "RTT",
          subtitle: "Réduction du temps de travail",
          color: "#43a047",
          validated: 0,
          daysTaken: 0,
        },
        {
          key: "exceptional",
          title: "Congés Exceptionnels",
          subtitle: "Selon la règlementation (motif requis)",
          color: "#fb8c00",
          validated: 0,
          daysTaken: 0,
        },
        {
          key: "unpaid",
          title: "Congés Sans Solde",
          subtitle: "Sur autorisation préalable",
          color: "#757575",
          validated: 0,
          daysTaken: 0,
        },
      ],
    };
  },
  mounted() {
    this.update_user_data()
  },
  computed: {
    getConge() {
      let conge = {
        pending: [],
        history: [],
        all: []
      }

      if (this.congeListe && this.congeListe.length > 0) {
        for (let i = 0; i < this.congeListe.length; i++) {
          if (this.congeListe[i].statut == 0) {
            conge.pending.push(this.congeListe[i])
          } else if (this.congeListe[i].statut > 0) {
            conge.history.push(this.congeListe[i])
          }
          conge.all.push(this.congeListe[i])
        }
      }

      return conge
    },
    initials() {
      const name = this.userInfo?.user_name || "";
      return name
        .split(" ")
        .map((w) => w[0])
        .join("")
        .toUpperCase()
        .slice(0, 2) || "?";
    },
    hireDate() {
      const ts = parseInt(this.userInfo?.date_embauche_timestamp);
      if (!ts) return "—";
      return new Date(ts * 1000).toLocaleDateString("fr-FR", {
        day: "2-digit",
        month: "long",
        year: "numeric",
      });
    },
    rttEligible() {
      return this.userInfo?.eligibilite_RTT == 1;
    },
    seniorityUsed() {
      const total = parseInt(this.userInfo?.jour_anciennete_total) || 0;
      const dispo = parseInt(this.userInfo?.jour_anciennete_dispo) || 0;
      return Math.max(0, total - dispo);
    },
    seniorityPercent() {
      const total = parseInt(this.userInfo?.jour_anciennete_total) || 0;
      if (total === 0) return 0;
      return Math.round((this.seniorityUsed / total) * 100);
    },
    filteredHistoryForExport() {
      return this.filterByPeriod(this.getConge.history);
    },
    leaveTypeOptions() {
      return this.congeTypes.map(t => ({
        label: t.libelle,
        value: t.id_conge_type,
        description: t.description,
        color: t.color,
        libelle: t.libelle,
      }));
    },
    selectedTypeIsExceptional() {
      if (!this.form.type) return false;
      const found = this.leaveTypeOptions.find(t => t.value === this.form.type);
      return found ? found.libelle.toLowerCase().includes('exception') : false;
    },
    workingDays() {
      const { dateDebut, dateFin } = this.form;
      if (!dateDebut || !dateFin || dateFin < dateDebut) return 0;
      let count = 0;
      const cur = new Date(dateDebut);
      const end = new Date(dateFin);
      while (cur <= end) {
        const d = cur.getDay();
        if (d !== 0 && d !== 6) count++;
        cur.setDate(cur.getDate() + 1);
      }
      return count;
    },
  },
  methods: {
    update_user_data() {
      this.update_user_solde()
      this.update_user_conges()
    },
    update_user_solde() {
      let that = this
      console.log("update_user_solde");

      engine.get_solde_by_user_id(this.userInfo.user_id, function (data) {
        console.log("data", data);

        if (data.code == 0) {
          that.soldeListe = data.data.data.data.map((val) => val.fieldData)
          console.log("soldeListe", that.soldeListe);

        }
      })
    },
    update_user_conges() {
      let that = this
      engine.get_conge_by_user_id(this.userInfo.user_id, function (data) {
        if (data.code == 0) {
          that.congeListe = data.data.data.data.map((val) => ({
            ...val.fieldData,
            _recordId: val.recordId,
          }))
        }
      })
    },
    getJoursPris(conge) {
      return this.getConge.history
        .filter(v => v.statut == 1 && v.id_conge_type == conge.id_conge_type)
        .reduce((sum, item) => sum + Number(item.nbr_days), 0);
    },
    getSoldeColor(solde) {
      const colorMap = {
        red: '#e53935', blue: '#3f51b5', green: '#43a047',
        orange: '#fb8c00', yellow: '#f9a825', purple: '#9c27b0',
        gray: '#757575', grey: '#757575', pink: '#e91e63',
        teal: '#00838f', cyan: '#00acc1', indigo: '#3f51b5',
      };
      const found = this.congeTypes.find(t => t.id_conge_type === solde.id_conge_type);
      if (!found) return '#3f51b5';
      return colorMap[found.color] || found.color || '#3f51b5';
    },
    updateNbrJours() {
      this.$nextTick(() => {
        this.form.nbrJours = this.workingDays || null;
      });
    },
    pad(n) {
      return String(n).padStart(2, "0");
    },
    formatDate(ts) {
      if (!ts) return "—";
      return new Date(parseInt(ts) * 1).toLocaleDateString("fr-FR", {
        day: "2-digit", month: "2-digit", year: "numeric",
      });
    },
    getTypeName(id) {
      const found = this.congeTypes.find(t => t.id_conge_type === id);
      return found ? found.libelle : id || "—";
    },
    getTypeColor(id) {
      const colorMap = {
        red: '#e53935', blue: '#3f51b5', green: '#43a047',
        orange: '#fb8c00', yellow: '#f9a825', purple: '#9c27b0',
        gray: '#757575', grey: '#757575', pink: '#e91e63',
        teal: '#00838f', cyan: '#00acc1', indigo: '#3f51b5',
      };
      const found = this.congeTypes.find(t => t.id_conge_type === id);
      if (!found) return '#757575';
      return colorMap[found.color] || found.color || '#757575';
    },
    parseMotif(commentaire) {
      if (!commentaire) return "—";
      try {
        const parsed = JSON.parse(commentaire);
        if (Array.isArray(parsed) && parsed[0]?.user) return parsed[0].user || "—";
      } catch {
        return commentaire;
      }
      return commentaire;
    },
    openDeleteRequestDialog(item) {
      this.requestToDelete = item;
      this.deleteRequestMotif = '';
      this.showDeleteRequestDialog = true;
    },
    confirmDeleteRequest() {
      if (!this.requestToDelete?.id_demande || !this.deleteRequestMotif.trim()) return;
      this.isRequestingDelete = true;
      let that = this;
      engine.update_conge_statut(this.requestToDelete.id_demande, 4, function () {
        that.isRequestingDelete = false;
        that.showDeleteRequestDialog = false;
        that.requestToDelete = null;
        that.deleteRequestMotif = '';
        that.update_user_conges();
      });
    },
    openCancelDialog(item) {
      this.requestToCancel = item;
      this.showCancelDialog = true;
    },
    confirmCancel() {
      if (!this.requestToCancel?.id_demande) return;
      this.isCancelling = true;
      let that = this;

      console.log("requestToCancel", this.requestToCancel);

      engine.update_conge_statut(this.requestToCancel.id_demande, 3, function () {
        that.isCancelling = false;
        that.showCancelDialog = false;
        that.requestToCancel = null;
        that.update_user_conges();
      });
    },
    filterByPeriod(items) {
      const now = new Date();
      let startDate = null;
      let endDate = null;
      if (this.exportPeriod === 'current') {
        startDate = new Date(now.getFullYear(), now.getMonth(), 1);
        endDate = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
      } else if (this.exportPeriod === 'previous') {
        startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        endDate = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59);
      } else if (this.exportPeriod === 'custom') {
        startDate = this.exportDateFrom ? new Date(this.exportDateFrom) : null;
        endDate = this.exportDateTo ? new Date(this.exportDateTo + 'T23:59:59') : null;
      } else {
        return items; // 'all'
      }
      return items.filter(item => {
        const d = new Date(parseInt(item.debut_timestamp));
        if (startDate && d < startDate) return false;
        if (endDate && d > endDate) return false;
        return true;
      });
    },
    doExportExcel() {
      const statusLabel = (statut) => {
        if (statut == 1) return 'Validée';
        if (statut == 2) return 'Refusée';
        return 'En attente';
      };

      const rows = this.filteredHistoryForExport.map((item) => ({
        'Type': this.getTypeName(item.id_conge_type),
        'Date début': this.formatDate(item.debut_timestamp),
        'Date fin': this.formatDate(item.fin_timestamp),
        'Jours': item.nbr_days || '—',
        'Motif': this.parseMotif(item.commentaire),
        'Statut': statusLabel(item.statut),
      }));

      const ws = XLSX.utils.json_to_sheet(rows);
      ws['!cols'] = [{ wch: 22 }, { wch: 14 }, { wch: 14 }, { wch: 8 }, { wch: 36 }, { wch: 12 }];

      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'Historique');

      const periodLabel = this.exportPeriod === 'current' ? moment().format('YYYY-MM')
        : this.exportPeriod === 'previous' ? moment().subtract(1, 'month').format('YYYY-MM')
          : this.exportPeriod === 'custom' ? `${this.exportDateFrom || ''}_${this.exportDateTo || ''}`
            : 'complet';
      const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
      const fileName = `historique_conges_${this.userInfo.user_name || 'export'}_${periodLabel}.xlsx`;
      saveAs(new Blob([wbout], { type: 'application/octet-stream' }), fileName);
      this.showExportDialog = false;
    },
    onCardClick(leave) {
      this.$emit("open-details", leave);
    },
    closeForm() {
      this.showRequestDialog = false;
      this.$nextTick(() => {
        this.form = { type: null, dateDebut: null, dateFin: null, nbrJours: null, motif: "" };
        this.dateDebutError = '';
        this.dateFinError = '';
        this.$refs.requestForm?.reset();
      });
    },
    async submitRequest() {

      // engine.run_conge_function('demande.accepter', { "id_demande": selectedRequest.id_demande }, function (data) {
      //   console.log("run_conge_function", data);
      //   that.isUpdating = false;
      //   that.showValidationModal = false;
      // })

      let that = this

      this.dateDebutError = '';
      this.dateFinError = '';
      if (!this.form.dateDebut) this.dateDebutError = 'Champ requis';
      if (!this.form.dateFin) this.dateFinError = 'Champ requis';
      else if (this.form.dateDebut && this.form.dateFin < this.form.dateDebut)
        this.dateFinError = 'Doit être après le début';
      if (this.dateDebutError || this.dateFinError) return;

      const { valid } = await this.$refs.requestForm.validate();
      if (!valid) return;
      this.isSubmitting = true;
      let payload = {
        statut: 0,
        id_conge_type: this.form.type,
        user_id: this.userInfo.user_id,
        debut_timestamp: parseInt(moment(this.form.dateDebut).format('x')),
        fin_timestamp: parseInt(moment(this.form.dateFin).format('x')),
        commentaire: JSON.stringify([{ 'user': this.form.motif }]),
        nbr_days: this.form.nbrJours ?? this.workingDays,
      };

      console.log("payload", payload);
      engine.run_conge_function('nouvelle.demande', payload, function (data) {
        console.log("run_conge_function", data);
        let scriptResult = JSON.parse(data.data.data.scriptResult)

        console.log("scriptResult", scriptResult);

        if (scriptResult.valide == true) {
          that.snackbar = {
            color: 'green',
            value: true,
            msg: 'Demande de congé en cours de traitement ' + (scriptResult.commentaire && scriptResult.commentaire.length > 0 ? scriptResult.commentaire : '')
          }
          engine.create_demande_conge(payload, function () {
            that.update_user_data()
          })
          that.showRequestDialog = false
          that.form = {}
        } else {
          that.snackbar = {
            color: 'red',
            value: true,
            msg: 'Demande de congé invalide ' + (scriptResult.commentaire && scriptResult.commentaire.length > 0 ? scriptResult.commentaire : '')
          }
        }
        that.isSubmitting = false;
        that.isUpdating = false;
      })

      // engine.create_demande_conge(payload, function () {
      //   that.update_user_conges()
      // })

      // this.isSubmitting = false;
      // this.closeForm();
    },
  },
};
</script>

